type RegisterChannelTypingReactionParams struct {
	ID                   string `json:"id"`
	WorkspaceID          string `json:"workspace_id"`
	ChatSessionID        string `json:"chat_session_id"`
	ChatMessageID        string `json:"chat_message_id"`
	InstallationID       string `json:"installation_id"`
	ChannelMessageID     string `json:"channel_message_id"`
	InstallationSnapshot string `json:"installation_snapshot"`
}

// Commit the complete external anchor BEFORE issuing Add. A terminal observer
// can enumerate every input, independently of the one delivery trigger.
func (q *Queries) RegisterChannelTypingReaction(ctx context.Context, arg RegisterChannelTypingReactionParams) (ChannelTypingReaction, error) {
	row := q.db.QueryRowContext(ctx, registerChannelTypingReaction,
		arg.ID,
		arg.WorkspaceID,
		arg.ChatSessionID,
		arg.ChatMessageID,
		arg.InstallationID,
		arg.ChannelMessageID,
		arg.InstallationSnapshot,
	)
	var i ChannelTypingReaction
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.ChatSessionID,
		&i.ChatMessageID,
		&i.InstallationID,
		&i.ChannelMessageID,
		&i.InstallationSnapshot,
		&i.ReactionID,
		&i.AddFinished,
		&i.CleanupRequired,
		&i.CleanedAt,
		&i.RetryAfter,
		&i.Attempts,
		&i.CreatedAt,
		&i.AbandonedAt,
		&i.QuotaSlot,
	)
	return i, err
}

const settleChannelTypingInputs = `-- name: SettleChannelTypingInputs :exec
UPDATE chat_message SET  channel_typing_settled = (SELECT true FROM chat_message AS cutoff, chat_session AS session, channel_installation AS installation WHERE cutoff.id = ?1 AND cutoff.chat_session_id = ?2
 AND session.id = ?2 AND session.workspace_id = ?3
 AND installation.id = ?4 AND installation.workspace_id = ?3
 AND installation.channel_type = 'feishu'
 AND EXISTS (SELECT 1 FROM channel_chat_session_binding b WHERE b.chat_session_id = session.id
  AND b.installation_id = installation.id AND b.channel_type = 'feishu')
 AND chat_message.chat_session_id = session.id AND chat_message.task_id IS NULL
 AND chat_message.channel_ingested AND chat_message.role = 'user'
 AND COALESCE(chat_message.channel_context_revision, 1) = ?5
 AND (chat_message.created_at, chat_message.id) <= (cutoff.created_at, cutoff.id)) WHERE EXISTS (SELECT 1 FROM chat_message AS cutoff, chat_session AS session, channel_installation AS installation WHERE cutoff.id = ?1 AND cutoff.chat_session_id = ?2
 AND session.id = ?2 AND session.workspace_id = ?3
 AND installation.id = ?4 AND installation.workspace_id = ?3
 AND installation.channel_type = 'feishu'
 AND EXISTS (SELECT 1 FROM channel_chat_session_binding b WHERE b.chat_session_id = session.id
  AND b.installation_id = installation.id AND b.channel_type = 'feishu')
 AND chat_message.chat_session_id = session.id AND chat_message.task_id IS NULL
 AND chat_message.channel_ingested AND chat_message.role = 'user'
 AND COALESCE(chat_message.channel_context_revision, 1) = ?5
 AND (chat_message.created_at, chat_message.id) <= (cutoff.created_at, cutoff.id))
`

type SettleChannelTypingInputsParams struct {
	ThroughMessageID string        `json:"through_message_id"`
	ChatSessionID    string        `json:"chat_session_id"`
	WorkspaceID      string        `json:"workspace_id"`
	InstallationID   string        `json:"installation_id"`
	ContextRevision  sql.NullInt64 `json:"context_revision"`
}

// The flush owns only this context's unowned inputs up to its captured cutoff.
// Later inputs, even in the same session, are not settled by this failed run.
func (q *Queries) SettleChannelTypingInputs(ctx context.Context, arg SettleChannelTypingInputsParams) error {
	_, err := q.db.ExecContext(ctx, settleChannelTypingInputs,
		arg.ThroughMessageID,
		arg.ChatSessionID,
		arg.WorkspaceID,
		arg.InstallationID,
		arg.ContextRevision,
	)
	return err
}

const skipChannelTypingReactionAdd = `-- name: SkipChannelTypingReactionAdd :exec
UPDATE channel_typing_reaction SET add_finished = true, cleanup_required = true,
 cleaned_at = now(), installation_snapshot = '{}' WHERE id = ?1 AND abandoned_at IS NULL
`

// No HTTP Add was issued for an already-settled input.
func (q *Queries) SkipChannelTypingReactionAdd(ctx context.Context, id string) error {
	_, err := q.db.ExecContext(ctx, skipChannelTypingReactionAdd, id)
	return err
}
